        VStack(alignment: .leading, spacing: 10) {
            HStack(spacing: 8) {
                Label(failed ? "Screenshot unreadable" : "Screen context", systemImage: failed ? "eye.slash" : "eye")
                    .font(type.meta)
                    .foregroundStyle(Theme.textSecondary)
                    .padding(.horizontal, 10)
                    .padding(.vertical, 4)
                    .background(Capsule().fill(Theme.raised))
                    .overlay(Capsule().strokeBorder(Theme.border, lineWidth: 1))
                Spacer()
            }
            if let summary {
                Text(summary)
                    .font(type.body)
                    .foregroundStyle(Theme.textPrimary)
                    .fixedSize(horizontal: false, vertical: true)
            }
        }
        .padding(Theme.Size.cardPadding)
        .frame(maxWidth: .infinity, alignment: .leading)
        .background(RoundedRectangle(cornerRadius: Theme.Radius.card, style: .continuous).fill(Theme.surface))
        .overlay(RoundedRectangle(cornerRadius: Theme.Radius.card, style: .continuous).strokeBorder(Theme.border, lineWidth: 1))
        .accessibilityElement(children: .combine)
    }
}

/// Confirmation card: summarizes exact writes and affected objects before acting.
struct ConfirmationCard: View {
    let title: String
    let details: [(String, String)]
    let onCancel: () -> Void
    let onConfirm: () -> Void

    @Environment(\.typeScale) private var type

    var body: some View {
        VStack(alignment: .leading, spacing: 14) {
            HStack {
                Label("Action confirmation", systemImage: "checkmark.circle")
                    .font(type.meta)
                    .foregroundStyle(Theme.textSecondary)
                    .padding(.horizontal, 10)
                    .padding(.vertical, 4)
                    .background(Capsule().fill(Theme.raised))
                    .overlay(Capsule().strokeBorder(Theme.border, lineWidth: 1))
                Spacer()
            }

            Text(title)
                .font(type.cardTitle)
                .foregroundStyle(Theme.textPrimary)

            VStack(spacing: 0) {
                ForEach(details.indices, id: \.self) { i in
                    let row = details[i]
                    HStack {
                        Text(row.0)
                            .font(type.body)
                            .foregroundStyle(Theme.textSecondary)
                        Spacer()
                        Text(row.1)
                            .font(type.bodyStrong)
                            .foregroundStyle(Theme.textPrimary)
                    }
                    .padding(.vertical, 10)
                    if i < details.count - 1 {
                        Divider().overlay(Theme.border)
                    }
                }
            }
            .padding(.horizontal, 14)
            .background(RoundedRectangle(cornerRadius: Theme.Radius.control).fill(Theme.raised))
            .overlay(RoundedRectangle(cornerRadius: Theme.Radius.control).strokeBorder(Theme.border, lineWidth: 1))

            HStack(spacing: 12) {
                Button("Cancel", action: onCancel)
                    .buttonStyle(BigButtonStyle(kind: .secondary))
                Button("Confirm", action: onConfirm)
                    .buttonStyle(BigButtonStyle(kind: .primary))
            }
            .padding(.top, 4)
        }
        .padding(Theme.Size.cardPadding)
        .frame(maxWidth: .infinity, alignment: .leading)
        .background(RoundedRectangle(cornerRadius: Theme.Radius.card, style: .continuous).fill(Theme.surface))
        .overlay(RoundedRectangle(cornerRadius: Theme.Radius.card, style: .continuous).strokeBorder(Theme.border, lineWidth: 1))
        .shadow(color: Theme.shadow, radius: 16, y: 8)
        .accessibilityElement(children: .contain)
    }
}

/// Done card: reports confirmed changes.
struct DoneCard: View {
    let message: String
    var onUndo: (() -> Void)? = nil

    @Environment(\.typeScale) private var type

    var body: some View {
        VStack(alignment: .leading, spacing: 12) {
            HStack(spacing: 8) {
                Image(systemName: "checkmark.circle.fill")
                    .font(type.cardTitle)
                    .foregroundStyle(Theme.textPrimary)
                Text("Changes saved")
                    .font(type.cardTitle)
                    .foregroundStyle(Theme.textPrimary)
                Spacer()
            }
            Text(message)
                .font(type.body)
                .foregroundStyle(Theme.textSecondary)
            if let onUndo {
                Button("Undo", action: onUndo)
                    .buttonStyle(BigButtonStyle(kind: .secondary))
            }
        }
        .padding(Theme.Size.cardPadding)
        .frame(maxWidth: .infinity, alignment: .leading)
        .background(RoundedRectangle(cornerRadius: Theme.Radius.card, style: .continuous).fill(Theme.surface))
        .overlay(RoundedRectangle(cornerRadius: Theme.Radius.card, style: .continuous).strokeBorder(Theme.border, lineWidth: 1))
    }
}

/// Error card: reports what failed with preserved context and retry/cancel actions.
struct ErrorCard: View {
    let message: String
    let contextText: String?
    let onRetry: (() -> Void)?
    let onCancel: (() -> Void)?

    @Environment(\.typeScale) private var type

    var body: some View {
        VStack(alignment: .leading, spacing: 12) {
            HStack(spacing: 8) {
                Image(systemName: "exclamationmark.triangle.fill")
                    .font(type.cardTitle)
                    .foregroundStyle(Theme.textPrimary)
                Text("Something went wrong")
                    .font(type.cardTitle)
                    .foregroundStyle(Theme.textPrimary)
            }
            Text(message)
                .font(type.body)
                .foregroundStyle(Theme.textPrimary)
            if let contextText {
                Text("Context: “\(contextText)”")
                    .font(type.meta)
                    .foregroundStyle(Theme.textSecondary)
            }
            if onRetry != nil || onCancel != nil {
                HStack(spacing: 12) {
                    if let onCancel {
                        Button("Cancel", action: onCancel)
                            .buttonStyle(BigButtonStyle(kind: .secondary))
                    }
                    if let onRetry {
                        Button("Retry", action: onRetry)
                            .buttonStyle(BigButtonStyle(kind: .primary))
                    }
                }
                .padding(.top, 4)
            }
        }
        .padding(Theme.Size.cardPadding)
        .frame(maxWidth: .infinity, alignment: .leading)
        .background(RoundedRectangle(cornerRadius: Theme.Radius.card, style: .continuous).fill(Theme.surface))
        .overlay(RoundedRectangle(cornerRadius: Theme.Radius.card, style: .continuous).strokeBorder(Theme.border, lineWidth: 1))
    }
}

/// Spec "IntentChip" on iPhone: capsules in a horizontal scroll row; each sends a typed turn.
private struct IntentChips: View {
    let ask: (String) -> Void
    @Environment(\.typeScale) private var type

    private let intents: [(String, String)] = [
        ("calendar", "Am I free?"),
        ("tram", "How do I get there?"),
        ("airplane", "When is my flight?"),
    ]

    var body: some View {
        ScrollView(.horizontal) {
            HStack(spacing: 8) {
                ForEach(intents, id: \.1) { icon, text in
                    Button { ask(text) } label: {
                        Label(text, systemImage: icon)
                            .font(type.label)
                            .foregroundStyle(Theme.textPrimary)
                            .padding(.horizontal, 14)
                            .frame(minHeight: Theme.Size.touchMin)
                            .background(Capsule().fill(Theme.surface))
                            .overlay(Capsule().strokeBorder(Theme.border, lineWidth: 1))
                    }
                }
            }
            .padding(.horizontal, Theme.Size.cardGutterMobile)
        }
        .scrollIndicators(.hidden)
    }
}

struct ConnectionBadge: View {
    let connection: AgentSession.Connection

    var body: some View {
        HStack(spacing: 6) {
            Image(systemName: icon)
                .font(.system(size: 11, weight: .semibold))
